def consistent(g, f):
    n=len(g); bad=[]
    for i in range(n):
        for j in range(n):
            a,b=g[i][j],g[f(i,j)[0]][f(i,j)[1]]
            if 2 not in (a,b) and a!=b: bad.append((i,j,a,b))
    return bad
