def solve2(gin):
    n=len(gin)
    val={}
    for i in range(n):
        for j in range(n):
            if gin[i][j]!=2: val[(i,j)]=gin[i][j]
    changed=True
    while changed:
        changed=False
        for i in range(n):
            for j in range(n):
                partners=[(n-1-i,j),(i,n-1-j),(n-1-i,n-1-j),(j,i)]
                known={val[p] for p in partners if p in val}
                assert len(known)<=1,(i,j,known)
                if known and (i,j) not in val:
                    val[(i,j)]=known.pop(); changed=True
    missing=[(i,j) for i in range(n) for j in range(n) if (i,j) not in val]
    return [[val[(i,j)] for j in range(n)] for i in range(n)], missing
